 446 |       <button id="btn-rug">🟫 Rug <span class="hint">[P]</span></button>
 447 |       <button id="btn-punch" title="Select a rect inside a table, then press U to punch a hole" style="cursor:default;opacity:0.75">🍩 Punch <span class="hint">[U]</span></button>
 448 |       <button id="btn-edit"   disabled>✏️ Edit <span class="hint">[E]</span></button>
 449 |       <button id="btn-delete" disabled>🗑️ Delete <span class="hint">[D]</span></button>
 450 |       <button id="btn-chaos">🌀 Chaos</button>
 451 |     </div>
 452 |     <div id="board-wrap">
