 469 |     <script>
 470 |       const CELL = 12, SIZE = 64;
 471 |       const board     = document.getElementById("board");
 472 |       const overlay   = document.getElementById("overlay");
 473 |       const selOverlay = document.getElementById("selection-overlay");
 474 |       const btnTable  = document.getElementById("btn-table");
 475 |       const btnCouch  = document.getElementById("btn-couch");
 476 |       const btnLsofa  = document.getElementById("btn-lsofa");
 477 |       const btnChair  = document.getElementById("btn-chair");
 478 |       const btnRug    = document.getElementById("btn-rug");
 479 |       const btnEdit   = document.getElementById("btn-edit");
 480 |       const btnDelete = document.getElementById("btn-delete");
 481 |       const boardWrap = document.getElementById("board-wrap");
 482 |       const couchGhostEl = document.getElementById("couch-ghost");
 483 |       const chairGhostEl = document.getElementById("chair-ghost");
 484 |       const lsofaGhostEl = document.getElementById("lsofa-ghost");
 485 |       const lsofaGhostCanvas = document.getElementById("lsofa-ghost-canvas");
 486 |       const rugCounterEl = document.getElementById("rug-counter");
 487 | 
 488 |       const TABLE_COLORS = [
 489 |         "#e07b54","#5b9bd5","#e8a838","#8e6bbf",
 490 |         "#4caf8a","#d95f8a","#6ab04c","#c0392b",
 491 |       ];
 492 | 
 493 |       // ── State ────────────────────────────────────────────────────────────────
 494 |       let tableCount = 0;
 495 |       const tables    = [];   // { id, rMin,cMin,rMax,cMax, color, label, el }
 496 |       const tableGrid = [];   // tableGrid[row][col] = array of piece ids occupying that cell
 497 |       let selectedTable = null;   // table currently clicked/focused
 498 |       let editingTable  = null;   // table lifted into edit mode
 499 | 
 500 |       let couchCount = 0;
 501 |       let couchMode  = false;     // true while couch-placement is active
 502 |       let ghostOrientation = "h"; // "h" or "v" — orientation of the next couch to be placed
 503 | 
 504 |       let chairCount = 0;
 505 |       let chairMode  = false;
 506 | 
 507 |       let lsofaCount = 0;
 508 |       let lsofaMode  = false;
 509 |       // Variants: "se" "sw" "ne" "nw" — which direction the two arms extend from the corner
 510 |       let lsofaVariant = "se";
 511 |       // Ghost arm lengths (editable via handles during placement ghost drag)
 512 |       let lsofaGhostLenA = 3; // horizontal arm (min 2)
 513 |       let lsofaGhostLenB = 3; // vertical arm   (min 2)
 514 | 
 515 |       let rugCount = 0;
 516 |       let rugMode  = false;
 517 |       const RUG_MAX_CELLS = 16;
 518 |       let rugPaintCells = new Set();
 519 | 
 520 |       let donutCount = 0;
 521 |       const DONUT_MIN_ROWS = 3, DONUT_MIN_COLS = 3;
 522 |       const DONUT_MAX_ROWS = 16, DONUT_MAX_COLS = 24;
 523 | 
 524 |       // ── Build cell grid ──────────────────────────────────────────────────────
 525 |       const cells = [];
 526 |       for (let row = 0; row < SIZE; row++) {
 527 |         cells[row] = []; tableGrid[row] = [];
 528 |         for (let col = 0; col < SIZE; col++) {
 529 |           const cell = document.createElement("div");
 530 |           cell.classList.add("cell");
 531 |           cell.classList.add((row + col) % 2 === 0 ? "light" : "dark");
 532 |           cell.dataset.row = row; cell.dataset.col = col;
 533 |           cells[row][col] = cell; tableGrid[row][col] = [];
 534 |           board.appendChild(cell);
 535 |         }
 536 |       }
 537 | 
 538 |       // ── Selection helpers ────────────────────────────────────────────────────
 539 |       let selection = null;
 540 |       let isSelecting = false, selStartRow = null, selStartCol = null;
 541 | 
 542 |       function clearClass(cls) {
 543 |         board.querySelectorAll("." + cls).forEach(c => c.classList.remove(cls));
 544 |       }
 545 |       function paintRect(r1,c1,r2,c2,cls) {
 546 |         for (let r=r1;r<=r2;r++) for (let c=c1;c<=c2;c++) cells[r][c].classList.add(cls);
 547 |       }
 548 |       function renderSelection() {
 549 |         clearClass("selected");
 550 |         if (selection) {
 551 |           paintRect(selection.rMin,selection.cMin,selection.rMax,selection.cMax,"selected");
