 609 |       function getPunchTarget(sel) {
 610 |         // Must leave at least 1-cell border → outer must be at least 3×3
 611 |         const outerRMin = sel.rMin - 1, outerCMin = sel.cMin - 1;
 612 |         const outerRMax = sel.rMax + 1, outerCMax = sel.cMax + 1;
 613 |         if (outerRMin < 0 || outerCMin < 0 || outerRMax >= SIZE || outerCMax >= SIZE) return null;
 614 |         // Every cell in the selection must belong to the same single table (type:"table")
 615 |         let target = null;
 616 |         for (let r=sel.rMin; r<=sel.rMax; r++) {
 617 |           for (let c=sel.cMin; c<=sel.cMax; c++) {
 618 |             const ids = tableGrid[r][c].filter(id => {
 619 |               const p = tables.find(t => t.id === id);
 620 |               return p && p.type === "table";
 621 |             });
 622 |             if (ids.length !== 1) return null;
 623 |             const piece = tables.find(t => t.id === ids[0]);
 624 |             if (!target) target = piece;
 625 |             else if (target !== piece) return null;
 626 |           }
 627 |         }
 628 |         if (!target) return null;
 629 |         // The outer ring cells must all also belong to the same target
 630 |         // (ensures the hole is truly interior, not on the edge of the table)
 631 |         if (target.rMin > outerRMin || target.cMin > outerCMin ||
 632 |             target.rMax < outerRMax || target.cMax < outerCMax) return null;
 633 |         return target;
 634 |       }
