 741 |       // ── Conflict detection ───────────────────────────────────────────────────
 742 |       // Returns true if the given rect overlaps any piece (optionally ignoring one id).
 743 |       function hasConflict(rMin,cMin,rMax,cMax,ignoreId=null) {
 744 |         for (let r=rMin;r<=rMax;r++) for (let c=cMin;c<=cMax;c++) {
