 752 |       // Chair-specific conflict: only blocks on non-chair pieces (chairs can stack).
 753 |       function hasConflictForChair(row, col, ignoreId=null) {
 754 |         for (const tid of tableGrid[row][col]) {
 755 |           if (tid === ignoreId) continue;
 756 |           const piece = tables.find(t => t.id === tid);
 757 |           if (piece && piece.type !== "chair") return true;
 758 |         }
 759 |         return false;
 760 |       }
