 767 |       // ── Place Table ──────────────────────────────────────────────────────────
 768 |       const TABLE_MIN_ROWS = 2, TABLE_MIN_COLS = 3;
 769 |       const TABLE_MAX_ROWS = 16, TABLE_MAX_COLS = 24;
