 771 |       /** Enforce table size limits on a raw selection rect. Returns clamped rect. */
 772 |       function clampTableSelection(rMin, cMin, rMax, cMax) {
 773 |         const rows = rMax - rMin + 1, cols = cMax - cMin + 1;
 774 |         // Enforce minimum
 775 |         const r2 = Math.min(rMin + Math.max(rows, TABLE_MIN_ROWS) - 1, SIZE - 1);
 776 |         const c2 = Math.min(cMin + Math.max(cols, TABLE_MIN_COLS) - 1, SIZE - 1);
 777 |         // Enforce maximum
 778 |         const r3 = Math.min(r2, rMin + TABLE_MAX_ROWS - 1);
 779 |         const c3 = Math.min(c2, cMin + TABLE_MAX_COLS - 1);
 780 |         return { rMin, cMin, rMax: r3, cMax: c3 };
 781 |       }
