 783 |       /**
 784 |        * Fracture any type:"table" pieces whose footprint overlaps the given rect.
 785 |        * The overlapping table is deleted and replaced by up to 4 non-overlapping
 786 |        * rectangular shards (top / bottom / left strip / right strip) using a
 787 |        * guillotine cut around the intersection.
 788 |        * Call this AFTER the new piece has been stamped so tableGrid is current.
 789 |        * Pass the new piece's id as `ignoreId` so we don't fracture the piece itself.
 790 |        */
 791 |       function fractureTablesUnder(nR1, nC1, nR2, nC2, ignoreId) {
 792 |         // Collect every table-type piece whose cells overlap the new rect
 793 |         const victims = new Set();
 794 |         for (let r = nR1; r <= nR2; r++) {
 795 |           for (let c = nC1; c <= nC2; c++) {
 796 |             for (const tid of tableGrid[r][c]) {
 797 |               if (tid === ignoreId) continue;
 798 |               const p = tables.find(t => t.id === tid);
 799 |               if (p && p.type === "table") victims.add(p);
 800 |             }
 801 |           }
 802 |         }
 803 |         for (const victim of victims) {
 804 |           // Intersection of victim with the new rect
 805 |           const oR1 = Math.max(victim.rMin, nR1), oC1 = Math.max(victim.cMin, nC1);
 806 |           const oR2 = Math.min(victim.rMax, nR2), oC2 = Math.min(victim.cMax, nC2);
 807 |           if (oR1 > oR2 || oC1 > oC2) continue; // no actual overlap (shouldn't happen)
 808 | 
 809 |           // Remember bounds before deletion
 810 |           const vR1 = victim.rMin, vC1 = victim.cMin;
 811 |           const vR2 = victim.rMax, vC2 = victim.cMax;
 812 |           const vColor = victim.color;
 813 | 
 814 |           deleteTable(victim);
 815 | 
 816 |           // Up to 4 shards — each only created if non-empty
 817 |           const shards = [
 818 |             { rMin: vR1,    cMin: vC1,    rMax: oR1-1, cMax: vC2    }, // top
 819 |             { rMin: oR2+1,  cMin: vC1,    rMax: vR2,   cMax: vC2    }, // bottom
 820 |             { rMin: oR1,    cMin: vC1,    rMax: oR2,   cMax: oC1-1  }, // left
 821 |             { rMin: oR1,    cMin: oC2+1,  rMax: oR2,   cMax: vC2    }, // right
 822 |           ];
 823 |           for (const s of shards) {
 824 |             if (s.rMin > s.rMax || s.cMin > s.cMax) continue; // empty shard
 825 |             spawnTable(s.rMin, s.cMin, s.rMax, s.cMax, vColor);
 826 |           }
 827 |         }
 828 |       }
