1274 |           case "ne": return { rMin: cornerR - lenB + 1, cMin: cornerC,            rMax: cornerR,            cMax: cornerC + lenA - 1 };
1275 |           case "nw": return { rMin: cornerR - lenB + 1, cMin: cornerC - lenA + 1, rMax: cornerR,            cMax: cornerC };
