469 |     <script>
470 |       const CELL = 12, SIZE = 64;
471 |       const board     = document.getElementById("board");
472 |       const overlay   = document.getElementById("overlay");
473 |       const selOverlay = document.getElementById("selection-overlay");
474 |       const btnTable  = document.getElementById("btn-table");
475 |       const btnCouch  = document.getElementById("btn-couch");
476 |       const btnLsofa  = document.getElementById("btn-lsofa");
477 |       const btnChair  = document.getElementById("btn-chair");
478 |       const btnRug    = document.getElementById("btn-rug");
479 |       const btnEdit   = document.getElementById("btn-edit");
480 |       const btnDelete = document.getElementById("btn-delete");
481 |       const boardWrap = document.getElementById("board-wrap");
482 |       const couchGhostEl = document.getElementById("couch-ghost");
483 |       const chairGhostEl = document.getElementById("chair-ghost");
484 |       const lsofaGhostEl = document.getElementById("lsofa-ghost");
485 |       const lsofaGhostCanvas = document.getElementById("lsofa-ghost-canvas");
486 |       const rugCounterEl = document.getElementById("rug-counter");
487 | 
488 |       const TABLE_COLORS = [
489 |         "#e07b54","#5b9bd5","#e8a838","#8e6bbf",
490 |         "#4caf8a","#d95f8a","#6ab04c","#c0392b",
491 |       ];
492 | 
493 |       // ── State ────────────────────────────────────────────────────────────────
494 |       let tableCount = 0;
495 |       const tables    = [];   // { id, rMin,cMin,rMax,cMax, color, label, el }
496 |       const tableGrid = [];   // tableGrid[row][col] = array of piece ids occupying that cell
497 |       let selectedTable = null;   // table currently clicked/focused
498 |       let editingTable  = null;   // table lifted into edit mode
499 | 
500 |       let couchCount = 0;

500 |       let couchCount = 0;
501 |       let couchMode  = false;     // true while couch-placement is active
502 |       let ghostOrientation = "h"; // "h" or "v" — orientation of the next couch to be placed
503 | 
504 |       let chairCount = 0;
505 |       let chairMode  = false;
506 | 
507 |       let lsofaCount = 0;
508 |       let lsofaMode  = false;
509 |       // Variants: "se" "sw" "ne" "nw" — which direction the two arms extend from the corner
510 |       let lsofaVariant = "se";
511 |       // Ghost arm lengths (editable via handles during placement ghost drag)
512 |       let lsofaGhostLenA = 3; // horizontal arm (min 2)
513 |       let lsofaGhostLenB = 3; // vertical arm   (min 2)
514 | 
515 |       let rugCount = 0;
516 |       let rugMode  = false;
517 |       const RUG_MAX_CELLS = 16;
518 |       let rugPaintCells = new Set();
519 | 
520 |       let donutCount = 0;
521 |       const DONUT_MIN_ROWS = 3, DONUT_MIN_COLS = 3;
522 |       const DONUT_MAX_ROWS = 16, DONUT_MAX_COLS = 24;
523 | 
524 |       // ── Build cell grid ──────────────────────────────────────────────────────
525 |       const cells = [];
526 |       for (let row = 0; row < SIZE; row++) {
527 |         cells[row] = []; tableGrid[row] = [];
528 |         for (let col = 0; col < SIZE; col++) {
529 |           const cell = document.createElement("div");
530 |           cell.classList.add("cell");
531 |           cell.classList.add((row + col) % 2 === 0 ? "light" : "dark");
532 |           cell.dataset.row = row; cell.dataset.col = col;
533 |           cells[row][col] = cell; tableGrid[row][col] = [];
534 |           board.appendChild(cell);
535 |         }
536 |       }
537 | 
538 |       // ── Selection helpers ────────────────────────────────────────────────────
539 |       let selection = null;
540 |       let isSelecting = false, selStartRow = null, selStartCol = null;
541 | 
542 |       function clearClass(cls) {
543 |         board.querySelectorAll("." + cls).forEach(c => c.classList.remove(cls));
544 |       }
545 |       function paintRect(r1,c1,r2,c2,cls) {
546 |         for (let r=r1;r<=r2;r++) for (let c=c1;c<=c2;c++) cells[r][c].classList.add(cls);
547 |       }
548 |       function renderSelection() {
549 |         clearClass("selected");
550 |         if (selection) {
551 |           paintRect(selection.rMin,selection.cMin,selection.rMax,selection.cMax,"selected");
552 |           selOverlay.style.left    = (selection.cMin * CELL) + "px";
553 |           selOverlay.style.top     = (selection.rMin * CELL) + "px";
554 |           selOverlay.style.width   = ((selection.cMax - selection.cMin + 1) * CELL) + "px";
555 |           selOverlay.style.height  = ((selection.rMax - selection.rMin + 1) * CELL) + "px";
556 |           selOverlay.style.display = "block";
557 |         } else {
558 |           selOverlay.style.display = "none";
559 |         }
560 |         btnTable.disabled = !selection;
561 |         btnEdit.disabled  = !selectedTable;
562 |       }
563 |       function selPreviewRect(curRow,curCol) {
564 |         const dr1=Math.min(selStartRow,curRow), dr2=Math.max(selStartRow,curRow);
565 |         const dc1=Math.min(selStartCol,curCol), dc2=Math.max(selStartCol,curCol);
566 |         let raw;
567 |         if (!selection) raw = {rMin:dr1,cMin:dc1,rMax:dr2,cMax:dc2};
568 |         else raw = {
569 |           rMin:Math.min(selection.rMin,dr1), cMin:Math.min(selection.cMin,dc1),
570 |           rMax:Math.max(selection.rMax,dr2), cMax:Math.max(selection.cMax,dc2),
571 |         };
572 |         const { rMin, cMin, rMax, cMax } = raw;
573 |         return clampTableSelection(rMin, cMin, rMax, cMax);
574 |       }
575 |       function applySelPreview(curRow,curCol) {
576 |         clearClass("preview");
577 |         clearClass("conflict");
578 |         clearClass("punch-preview");
579 |         clearClass("punch-conflict");
580 |         const r = selPreviewRect(curRow,curCol);
581 |         const punchTarget = getPunchTarget(r);
582 |         if (punchTarget) {
583 |           // All cells in selection get punch-preview colour
584 |           for (let row=r.rMin;row<=r.rMax;row++)
585 |             for (let col=r.cMin;col<=r.cMax;col++)
586 |               cells[row][col].classList.add("punch-preview");
587 |         } else {
588 |           for (let row=r.rMin;row<=r.rMax;row++) {
589 |             for (let col=r.cMin;col<=r.cMax;col++) {
590 |               if (tableGrid[row][col].length > 0) {
591 |                 cells[row][col].classList.add("conflict");
592 |               } else {
593 |                 cells[row][col].classList.add("preview");
594 |               }
595 |             }
596 |           }
597 |         }
598 |         selOverlay.style.left    = (r.cMin * CELL) + "px";
599 |         selOverlay.style.top     = (r.rMin * CELL) + "px";
600 |         selOverlay.style.width   = ((r.cMax - r.cMin + 1) * CELL) + "px";
601 |         selOverlay.style.height  = ((r.rMax - r.rMin + 1) * CELL) + "px";
602 |         selOverlay.style.display = "block";
603 |       }
604 | 
605 |       /**
606 |        * If `sel` is a valid punch rect (completely inside exactly one plain table
607 |        * with ≥1 cell margin on all sides), return that table. Otherwise null.
608 |        */
609 |       function getPunchTarget(sel) {
610 |         // Must leave at least 1-cell border → outer must be at least 3×3
611 |         const outerRMin = sel.rMin - 1, outerCMin = sel.cMin - 1;
612 |         const outerRMax = sel.rMax + 1, outerCMax = sel.cMax + 1;
613 |         if (outerRMin < 0 || outerCMin < 0 || outerRMax >= SIZE || outerCMax >= SIZE) return null;
614 |         // Every cell in the selection must belong to the same single table (type:"table")
615 |         let target = null;
616 |         for (let r=sel.rMin; r<=sel.rMax; r++) {
617 |           for (let c=sel.cMin; c<=sel.cMax; c++) {
618 |             const ids = tableGrid[r][c].filter(id => {
619 |               const p = tables.find(t => t.id === id);
620 |               return p && p.type === "table";
621 |             });
622 |             if (ids.length !== 1) return null;
623 |             const piece = tables.find(t => t.id === ids[0]);
624 |             if (!target) target = piece;
625 |             else if (target !== piece) return null;
626 |           }
627 |         }
628 |         if (!target) return null;
629 |         // The outer ring cells must all also belong to the same target
630 |         // (ensures the hole is truly interior, not on the edge of the table)
631 |         if (target.rMin > outerRMin || target.cMin > outerCMin ||
632 |             target.rMax < outerRMax || target.cMax < outerCMax) return null;
633 |         return target;
634 |       }
