637 |       // ── Cell colour helpers ──────────────────────────────────────────────────
638 |       function resetCell(r,c) {
639 |         const cell = cells[r][c];
640 |         cell.style.backgroundColor = "";
641 |         cell.style.opacity = "";
642 |         cell.classList.remove("selected","preview");
643 |         cell.classList.add((r+c)%2===0 ? "light" : "dark");
644 |         tableGrid[r][c] = [];
645 |       }
646 |       function stampTable(t) {
647 |         for (let r=t.rMin;r<=t.rMax;r++) for (let c=t.cMin;c<=t.cMax;c++) {
648 |           if (!tableGrid[r][c].includes(t.id)) tableGrid[r][c].push(t.id);
649 |           if (t.type === "chair") refreshChairBadge(r, c);
650 |         }
651 |       }
652 |       function eraseTable(t) {
653 |         for (let r=t.rMin;r<=t.rMax;r++) for (let c=t.cMin;c<=t.cMax;c++) {
654 |           tableGrid[r][c] = tableGrid[r][c].filter(id => id !== t.id);
655 |           if (tableGrid[r][c].length === 0) resetCell(r, c);
656 |           if (t.type === "chair") refreshChairBadge(r, c);
