content = r"""<!DOCTYPE html>
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>Room Packer 3D</title>
    <script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>
    <style>
      * { margin: 0; padding: 0; box-sizing: border-box; }
      body {
        background: #1a1a2e;
        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: flex-start;
        min-height: 100vh;
        font-family: sans-serif;
        overflow: hidden;
      }
      #toolbar {
        display: flex;
        gap: 10px;
        align-items: center;
        padding: 10px 16px;
        background: rgba(0,0,0,0.45);
        width: 100%;
        flex-wrap: wrap;
        z-index: 10;
      }
      #toolbar button {
        background: #2e4a7a; color: #fff;
        border: 2px solid #4a7abf; border-radius: 6px;
        padding: 8px 16px; font-size: 13px; cursor: pointer;
        transition: background 0.15s, border-color 0.15s;
      }
      #toolbar button:hover    { background: #3a5d99; border-color: #6a9acf; }
      #toolbar button:disabled { opacity: 0.35; cursor: not-allowed; }
      #toolbar button.active   { background: #5a3a8a; border-color: #9a6acf; }
      #toolbar .hint           { color: #aac; font-size: 11px; }
      #canvas-wrap {
        position: relative;
        flex: 1;
        width: 100%;
        height: calc(100vh - 56px);
      }
      #three-canvas { display: block; width: 100%; height: 100%; }
      #hud {
        position: absolute; bottom: 12px; left: 50%; transform: translateX(-50%);
        color: #aac; font-size: 12px; pointer-events: none; text-align: center;
        background: rgba(0,0,0,0.45); padding: 6px 14px; border-radius: 6px;
        white-space: nowrap;
      }
      #rug-counter {
        position: absolute; bottom: 50px; left: 50%; transform: translateX(-50%);
        color: #ffd; font-size: 13px; pointer-events: none;
        background: rgba(0,0,0,0.6); padding: 5px 14px; border-radius: 6px;
        display: none;
      }
      #rug-counter.at-limit { color: #f55; }
      #gameover-overlay {
        display: none; position: fixed; inset: 0;
        background: rgba(0,0,0,0.82); z-index: 100;
        flex-direction: column; align-items: center; justify-content: center;
        gap: 18px; color: #fff;
      }
      #gameover-overlay.visible { display: flex; }
      #gameover-overlay h1 { font-size: 56px; letter-spacing: 4px; color: #e05555; }
      #gameover-overlay p  { font-size: 18px; text-align: center; max-width: 420px; line-height: 1.5; }
      #gameover-overlay button {
        background: #2e4a7a; color: #fff; border: 2px solid #4a7abf;
        border-radius: 6px; padding: 12px 36px; font-size: 18px; cursor: pointer;
      }
      #gameover-overlay button:hover { background: #3a5d99; }
    </style>
  </head>
  <body>
    <div id="toolbar">
      <button id="btn-table" disabled>&#127825; Table <span class="hint">[T] drag grid</span></button>
      <button id="btn-couch">&#128715; Sofa <span class="hint">[C]</span></button>
      <button id="btn-lsofa">&#128208; L-Sofa <span class="hint">[L]</span></button>
      <button id="btn-chair">&#129681; Chair <span class="hint">[H]</span></button>
      <button id="btn-rug">&#129039; Rug <span class="hint">[P]</span></button>
      <button id="btn-delete" disabled>&#128465; Delete <span class="hint">[D]</span></button>
      <button id="btn-chaos">&#127744; Chaos</button>
    </div>
    <div id="canvas-wrap">
      <canvas id="three-canvas"></canvas>
      <div id="hud">Drag empty floor = select table area &middot; Drag piece = move &middot; Right-drag / scroll = orbit/zoom &middot; [R] rotate &middot; [D] delete &middot; [Esc] cancel</div>
      <div id="rug-counter">0 / 16 cells &#8212; Enter to place, Esc to cancel</div>
    </div>
    <div id="gameover-overlay">
      <h1>GAME OVER</h1>
      <p id="gameover-msg">A piece sat in conflict too long.</p>
      <button onclick="location.reload()">Try Again</button>
    </div>

    <script>
    // ═══════════════════════════════════════════════════════════════════
    //  Room Packer 3D  — Three.js isometric renderer
    // ═══════════════════════════════════════════════════════════════════
    const SIZE = 32;          // grid cells per side
    const CELL = 1.0;         // world-units per grid cell

    // Piece heights (world-units)
    const H_TABLE = 0.70;
    const H_COUCH = 0.55;
    const H_LSOFA = 0.55;
    const H_CHAIR = 0.42;
    const H_RUG   = 0.07;

    // ── Three.js setup ─────────────────────────────────────────────────
    const canvas   = document.getElementById("three-canvas");
    const wrap     = document.getElementById("canvas-wrap");
    const renderer = new THREE.WebGLRenderer({ canvas, antialias: true });
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type    = THREE.PCFSoftShadowMap;
    renderer.setClearColor(0x1a1a2e);

    // Orthographic camera
    const VIEW   = SIZE * CELL * 0.9;
    let   aspect = 1;
    const camera = new THREE.OrthographicCamera(-VIEW, VIEW, VIEW, -VIEW, -500, 500);

    const scene = new THREE.Scene();
    scene.fog = new THREE.FogExp2(0x1a1a2e, 0.009);

    // Lighting
    scene.add(new THREE.AmbientLight(0xffffff, 0.6));
    const sun = new THREE.DirectionalLight(0xfff8e7, 0.9);
    sun.position.set(30, 60, 40);
    sun.castShadow = true;
    sun.shadow.mapSize.set(2048, 2048);
    sun.shadow.camera.left = -60; sun.shadow.camera.right  =  60;
    sun.shadow.camera.top  =  60; sun.shadow.camera.bottom = -60;
    sun.shadow.camera.near = 1;   sun.shadow.camera.far    = 300;
    scene.add(sun);
    const fill = new THREE.DirectionalLight(0xc8d8ff, 0.25);
    fill.position.set(-20, 20, -10);
    scene.add(fill);

    // ── Floor grid ─────────────────────────────────────────────────────
    const floorGroup = new THREE.Group();
    scene.add(floorGroup);
    const tileGeoFloor  = new THREE.BoxGeometry(CELL, 0.08, CELL);
    const matLight = new THREE.MeshLambertMaterial({ color: 0xf0d9b5 });
    const matDark  = new THREE.MeshLambertMaterial({ color: 0xb58863 });
    const tileObjs = [];
    for (let r = 0; r < SIZE; r++) {
      tileObjs[r] = [];
      for (let c = 0; c < SIZE; c++) {
        const m = new THREE.Mesh(tileGeoFloor, (r+c)%2===0 ? matLight : matDark);
        m.position.set(c + 0.5, -0.04, r + 0.5);
        m.receiveShadow = true;
        m.userData = { isTile: true, row: r, col: c };
        floorGroup.add(m);
        tileObjs[r][c] = m;
      }
    }
    // Grid border
    const bGeo = new THREE.EdgesGeometry(new THREE.BoxGeometry(SIZE*CELL, 0.01, SIZE*CELL));
    const bMat = new THREE.LineBasicMaterial({ color: 0x666688 });
    const bLine = new THREE.LineSegments(bGeo, bMat);
    bLine.position.set(SIZE/2, 0.01, SIZE/2);
    scene.add(bLine);

    // ── State ──────────────────────────────────────────────────────────
    let pieceCounter = 0;
    const pieces    = [];
    const gridOccupancy = [];  // gridOccupancy[r][c] = [pieceId, ...]
    for (let r = 0; r < SIZE; r++) {
      gridOccupancy[r] = [];
      for (let c = 0; c < SIZE; c++) gridOccupancy[r][c] = [];
    }

    let selectedPiece  = null;
    let couchMode      = false, ghostOrientation = "h";
    let chairMode      = false;
    let lsofaMode      = false, lsofaVariant = "se";
    let lsofaGhostLenA = 3, lsofaGhostLenB = 3;
    let rugMode        = false, rugCount = 0;
    let rugPaintCells  = new Set();
    let gameOver       = false;

    // Selection drag state
    let selDragging = false, selStart = null, selRect = null;
    let selMesh = null;

    // Drag-move state
    let draggingPiece = null, dragOffR = 0, dragOffC = 0;

    // Ghost meshes
    let ghostMeshes = [];
    function clearGhosts() {
      for (const m of ghostMeshes) scene.remove(m);
      ghostMeshes = [];
    }
    function addGhostBox(rMin, cMin, rMax, cMax, height, color, conflict) {
      const cols = cMax-cMin+1, rows = rMax-rMin+1;
      const geo  = new THREE.BoxGeometry(cols*CELL, height, rows*CELL);
      const mat  = new THREE.MeshBasicMaterial({
        color: conflict ? 0xff4444 : color,
        transparent: true, opacity: 0.4,
      });
      const m = new THREE.Mesh(geo, mat);
      m.position.set(cMin*CELL+cols*CELL/2, height/2+0.02, rMin*CELL+rows*CELL/2);
      scene.add(m);
      ghostMeshes.push(m);
    }
    function addGhostCells(cells, height, color, conflict) {
      const geo = new THREE.BoxGeometry(CELL*0.94, height, CELL*0.94);
      for (const {r,c} of cells) {
        const cellConflict = conflict || (r<0||c<0||r>=SIZE||c>=SIZE);
        const mat = new THREE.MeshBasicMaterial({
          color: cellConflict ? 0xff4444 : color,
          transparent: true, opacity: 0.45,
        });
        const m = new THREE.Mesh(geo, mat);
        m.position.set(c+0.5, height/2+0.02, r+0.5);
        scene.add(m);
        ghostMeshes.push(m);
      }
    }

    // Selection highlight
    let selHighlight = null;
    function updateSelHighlight(p) {
      if (selHighlight) { scene.remove(selHighlight); selHighlight = null; }
      if (!p) return;
      const W = (p.cMax-p.cMin+1)*CELL + 0.18;
      const D = (p.rMax-p.rMin+1)*CELL + 0.18;
      const geo = new THREE.BoxGeometry(W, 0.06, D);
      const mat = new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.35 });
      selHighlight = new THREE.Mesh(geo, mat);
      selHighlight.position.set(
        p.cMin*CELL+(p.cMax-p.cMin+1)*CELL/2,
        p.height + 0.07,
        p.rMin*CELL+(p.rMax-p.rMin+1)*CELL/2
      );
      scene.add(selHighlight);
    }

    // Selection rect highlight (for placing tables)
    function setSelRect(rMin, cMin, rMax, cMax, conflict) {
      if (selMesh) { scene.remove(selMesh); selMesh = null; }
      const cols = cMax-cMin+1, rows = rMax-rMin+1;
      const geo  = new THREE.BoxGeometry(cols*CELL, 0.14, rows*CELL);
      const mat  = new THREE.MeshBasicMaterial({
        color: conflict ? 0xe05555 : 0x7fc97f,
        transparent: true, opacity: 0.5,
      });
      selMesh = new THREE.Mesh(geo, mat);
      selMesh.position.set(cMin*CELL+cols*CELL/2, 0.09, rMin*CELL+rows*CELL/2);
      scene.add(selMesh);
    }
    function clearSelRect() {
      if (selMesh) { scene.remove(selMesh); selMesh = null; }
    }

    // ── Colour palettes ────────────────────────────────────────────────
    const TABLE_COLORS = [0xe07b54,0x5b9bd5,0xe8a838,0x8e6bbf,0x4caf8a,0xd95f8a,0x6ab04c,0xc0392b];
    const COUCH_COLORS = [0xb86fc4,0x7a6bc4,0x4fa8d0,0x4db89e,0xd4a03e,0xd06060,0x6ba05a,0x9a8060];
    const RUG_COLORS   = [0xe07b54,0x5b9bd5,0x8e6bbf,0x4caf8a,0xd95f8a,0xe8a838,0x6ab04c,0xc0392b];
    const CHAIR_COLOR  = 0x4ecdc4;

    // ── Grid helpers ───────────────────────────────────────────────────
    function stampRect(id, rMin,cMin,rMax,cMax) {
      for (let r=rMin;r<=rMax;r++) for (let c=cMin;c<=cMax;c++)
        if (!gridOccupancy[r][c].includes(id)) gridOccupancy[r][c].push(id);
    }
    function eraseRect(id, rMin,cMin,rMax,cMax) {
      for (let r=rMin;r<=rMax;r++) for (let c=cMin;c<=cMax;c++)
        gridOccupancy[r][c] = gridOccupancy[r][c].filter(x=>x!==id);
    }
    function stampCells(id, cells) {
      for (const {r,c} of cells)
        if (!gridOccupancy[r][c].includes(id)) gridOccupancy[r][c].push(id);
    }
    function eraseCells(id, cells) {
      for (const {r,c} of cells)
        gridOccupancy[r][c] = gridOccupancy[r][c].filter(x=>x!==id);
    }

    // ── Conflict detection ─────────────────────────────────────────────
    function hasConflict(rMin,cMin,rMax,cMax,ignoreId=null) {
      for (let r=rMin;r<=rMax;r++) for (let c=cMin;c<=cMax;c++)
        for (const id of gridOccupancy[r][c]) if (id!==ignoreId) return true;
      return false;
    }
    function hasConflictCells(cells, ignoreId=null) {
      for (const {r,c} of cells) {
        if (r<0||c<0||r>=SIZE||c>=SIZE) return true;
        for (const id of gridOccupancy[r][c]) if (id!==ignoreId) return true;
      }
      return false;
    }

    // ── Mesh factory ───────────────────────────────────────────────────
    function makeBoxMesh(cols, rows, height, colorHex) {
      const geo = new THREE.BoxGeometry(cols*CELL, height, rows*CELL);
      const mat = new THREE.MeshLambertMaterial({ color: colorHex });
      const mesh = new THREE.Mesh(geo, mat);
      mesh.castShadow = mesh.receiveShadow = true;
      // Edge outline
      const eGeo = new THREE.EdgesGeometry(geo);
      const eMat = new THREE.LineBasicMaterial({ color: 0x000000, transparent:true, opacity:0.28 });
      mesh.add(new THREE.LineSegments(eGeo, eMat));
      return mesh;
    }
    function positionBoxMesh(mesh, rMin,cMin,rMax,cMax, height) {
      const cols=cMax-cMin+1, rows=rMax-rMin+1;
      mesh.position.set(cMin*CELL+cols*CELL/2, height/2, rMin*CELL+rows*CELL/2);
    }

    // ── Piece color update (for conflicts) ─────────────────────────────
    function setMeshColor(obj, hex) {
      obj.traverse(ch => {
        if (ch.isMesh && ch.material && !ch.material.wireframe && ch.material.color)
          ch.material.color.setHex(hex);
      });
    }
    function refreshPieceColor(p) {
      const conflict = p.cells
        ? hasConflictCells(p.cells, p.id)
        : hasConflict(p.rMin,p.cMin,p.rMax,p.cMax,p.id);
      setMeshColor(p.mesh, conflict ? 0xe05555 : p.color);
    }
    function refreshAllColors() { for (const p of pieces) refreshPieceColor(p); }

    // ── Place pieces ───────────────────────────────────────────────────
    const TABLE_MIN_ROWS=2, TABLE_MIN_COLS=3, TABLE_MAX_ROWS=16, TABLE_MAX_COLS=24;

    function placeTable(rMin,cMin,rMax,cMax) {
      const rows=rMax-rMin+1, cols=cMax-cMin+1;
      if (rows<TABLE_MIN_ROWS||cols<TABLE_MIN_COLS) return null;
      if (rows>TABLE_MAX_ROWS||cols>TABLE_MAX_COLS) return null;
      const id=pieceCounter++, color=TABLE_COLORS[id%TABLE_COLORS.length];
      const mesh=makeBoxMesh(cols,rows,H_TABLE,color);
      positionBoxMesh(mesh,rMin,cMin,rMax,cMax,H_TABLE);
      scene.add(mesh); mesh.userData.pieceId=id;
      const p={id,type:"table",rMin,cMin,rMax,cMax,color,label:`Table ${id+1}`,mesh,height:H_TABLE};
      pieces.push(p); stampRect(id,rMin,cMin,rMax,cMax);
      return p;
    }

    function placeCouch(rMin,cMin,rMax,cMax,orientation) {
      const id=pieceCounter++;
      const color=COUCH_COLORS[pieces.filter(p=>p.type==="couch").length%COUCH_COLORS.length];
      const cols=cMax-cMin+1, rows=rMax-rMin+1;
      const mesh=makeBoxMesh(cols,rows,H_COUCH,color);
      positionBoxMesh(mesh,rMin,cMin,rMax,cMax,H_COUCH);
      scene.add(mesh); mesh.userData.pieceId=id;
      const p={id,type:"couch",rMin,cMin,rMax,cMax,color,label:`Sofa ${id+1}`,mesh,height:H_COUCH,orientation};
      pieces.push(p); stampRect(id,rMin,cMin,rMax,cMax);
      return p;
    }

    function placeChair(r,c) {
      const id=pieceCounter++;
      const geo=new THREE.CylinderGeometry(0.36,0.36,H_CHAIR,20);
      const mat=new THREE.MeshLambertMaterial({color:CHAIR_COLOR});
      const mesh=new THREE.Mesh(geo,mat);
      mesh.castShadow=true; mesh.position.set(c+0.5,H_CHAIR/2,r+0.5);
      mesh.userData.pieceId=id;
      scene.add(mesh);
      const p={id,type:"chair",rMin:r,cMin:c,rMax:r,cMax:c,color:CHAIR_COLOR,label:`Chair ${id+1}`,mesh,height:H_CHAIR};
      pieces.push(p); stampRect(id,r,c,r,c);
      return p;
    }

    function lsofaCells(aR,aC,lenA,lenB,variant) {
      const set=new Set();
      const add=(r1,c1,r2,c2)=>{for(let r=r1;r<=r2;r++)for(let c=c1;c<=c2;c++)set.add(`${r},${c}`);};
      if (variant==="se"){ add(aR,aC,aR+1,aC+lenA-1); add(aR,aC,aR+lenB-1,aC+1); }
      else if(variant==="sw"){ add(aR,aC-lenA+1,aR+1,aC); add(aR,aC-1,aR+lenB-1,aC); }
      else if(variant==="ne"){ add(aR-1,aC,aR,aC+lenA-1); add(aR-lenB+1,aC,aR,aC+1); }
      else { add(aR-1,aC-lenA+1,aR,aC); add(aR-lenB+1,aC-1,aR,aC); }
      return [...set].map(k=>{const[r,c]=k.split(",").map(Number);return{r,c};});
    }
    function bboxOf(cells){
      let rMin=Infinity,cMin=Infinity,rMax=-Infinity,cMax=-Infinity;
      for(const{r,c}of cells){rMin=Math.min(rMin,r);cMin=Math.min(cMin,c);rMax=Math.max(rMax,r);cMax=Math.max(cMax,c);}
      return{rMin,cMin,rMax,cMax};
    }

    function placeLsofa(aR,aC,lenA,lenB,variant) {
      const cellArr=lsofaCells(aR,aC,lenA,lenB,variant);
      if(cellArr.some(({r,c})=>r<0||c<0||r>=SIZE||c>=SIZE)) return null;
      const id=pieceCounter++;
      const color=COUCH_COLORS[pieces.filter(p=>p.type==="lsofa").length%COUCH_COLORS.length];
      const bb=bboxOf(cellArr);
      const group=new THREE.Group();
      const geo=new THREE.BoxGeometry(CELL*0.95,H_LSOFA,CELL*0.95);
      const mat=new THREE.MeshLambertMaterial({color});
      for(const{r,c}of cellArr){
        const m=new THREE.Mesh(geo,mat); m.castShadow=true;
        m.position.set(c+0.5,H_LSOFA/2,r+0.5); group.add(m);
      }
      scene.add(group); group.userData.pieceId=id;
      const p={id,type:"lsofa",rMin:bb.rMin,cMin:bb.cMin,rMax:bb.rMax,cMax:bb.cMax,
               cells:cellArr,anchorR:aR,anchorC:aC,lenA,lenB,variant,
               color,label:`L-Sofa ${id+1}`,mesh:group,height:H_LSOFA};
      pieces.push(p); stampCells(id,cellArr);
      return p;
    }

    const RUG_MAX_CELLS=16;
    function placeRug(cellArr) {
      const id=pieceCounter++; rugCount++;
      const color=RUG_COLORS[(rugCount-1)%RUG_COLORS.length];
      const bb=bboxOf(cellArr);
      const group=new THREE.Group();
      const geo=new THREE.BoxGeometry(CELL*0.9,H_RUG,CELL*0.9);
      const mat=new THREE.MeshLambertMaterial({color,transparent:true,opacity:0.85});
      for(const{r,c}of cellArr){
        const m=new THREE.Mesh(geo,mat); m.receiveShadow=true;
        m.position.set(c+0.5,H_RUG/2,r+0.5); group.add(m);
      }
      scene.add(group); group.userData.pieceId=id;
      const p={id,type:"rug",rMin:bb.rMin,cMin:bb.cMin,rMax:bb.rMax,cMax:bb.cMax,
               cells:cellArr,color,label:`Rug ${rugCount}`,mesh:group,height:H_RUG};
      pieces.push(p); stampCells(id,cellArr);
      return p;
    }

    // ── Delete ─────────────────────────────────────────────────────────
    function deletePiece(p) {
      if(!p) return;
      scene.remove(p.mesh);
      if(p.cells) eraseCells(p.id,p.cells);
      else eraseRect(p.id,p.rMin,p.cMin,p.rMax,p.cMax);
      pieces.splice(pieces.indexOf(p),1);
      if(selectedPiece===p) selectPiece(null);
    }

    // ── Rotate ─────────────────────────────────────────────────────────
    function rebuildMesh(p) {
      scene.remove(p.mesh);
      if(p.type==="table"||p.type==="couch") {
        const cols=p.cMax-p.cMin+1,rows=p.rMax-p.rMin+1;
        p.mesh=makeBoxMesh(cols,rows,p.height,p.color);
        positionBoxMesh(p.mesh,p.rMin,p.cMin,p.rMax,p.cMax,p.height);
        scene.add(p.mesh); p.mesh.userData.pieceId=p.id;
      } else if(p.type==="lsofa"||p.type==="rug") {
        const group=new THREE.Group();
        const geo=new THREE.BoxGeometry(
          p.type==="lsofa"?CELL*0.95:CELL*0.9,
          p.height,
          p.type==="lsofa"?CELL*0.95:CELL*0.9
        );
        const mat=new THREE.MeshLambertMaterial({
          color:p.color,
          transparent:p.type==="rug",
          opacity:p.type==="rug"?0.85:1
        });
        for(const{r,c}of p.cells){
          const m=new THREE.Mesh(geo,mat);
          m.castShadow=true; m.position.set(c+0.5,p.height/2,r+0.5); group.add(m);
        }
        scene.add(group); group.userData.pieceId=p.id; p.mesh=group;
      }
      refreshPieceColor(p);
    }

    function rotatePiece(p) {
      if(!p) return;
      if(p.type==="table"||p.type==="couch") {
        const h=p.rMax-p.rMin,w=p.cMax-p.cMin;
        eraseRect(p.id,p.rMin,p.cMin,p.rMax,p.cMax);
        if(p.type==="couch") p.orientation=p.orientation==="h"?"v":"h";
        p.rMax=Math.min(p.rMin+w,SIZE-1); p.cMax=Math.min(p.cMin+h,SIZE-1);
        stampRect(p.id,p.rMin,p.cMin,p.rMax,p.cMax);
        rebuildMesh(p);
      } else if(p.type==="lsofa") {
        const vs=["se","sw","nw","ne"];
        const ni=(vs.indexOf(p.variant)+1)%4;
        const newVariant=vs[ni];
        const newCells=lsofaCells(p.anchorR,p.anchorC,p.lenA,p.lenB,newVariant);
        if(newCells.some(({r,c})=>r<0||c<0||r>=SIZE||c>=SIZE)) return;
        eraseCells(p.id,p.cells); p.variant=newVariant; p.cells=newCells;
        const bb=bboxOf(newCells); p.rMin=bb.rMin;p.cMin=bb.cMin;p.rMax=bb.rMax;p.cMax=bb.cMax;
        stampCells(p.id,p.cells); rebuildMesh(p);
      } else if(p.type==="rug") {
        const H=p.rMax-p.rMin+1;
        const rotated=p.cells.map(({r,c})=>{
          const dr=r-p.rMin,dc=c-p.cMin; return{r:p.rMin+dc,c:p.cMin+(H-1-dr)};
        });
        const bb=bboxOf(rotated);
        const dr=Math.max(0,-bb.rMin)+Math.min(0,SIZE-1-bb.rMax);
        const dc=Math.max(0,-bb.cMin)+Math.min(0,SIZE-1-bb.cMax);
        const clamped=rotated.map(({r,c})=>({r:r+dr,c:c+dc}));
        eraseCells(p.id,p.cells); p.cells=clamped;
        const bb2=bboxOf(clamped); p.rMin=bb2.rMin;p.cMin=bb2.cMin;p.rMax=bb2.rMax;p.cMax=bb2.cMax;
        stampCells(p.id,p.cells); rebuildMesh(p);
      }
      updateSelHighlight(selectedPiece);
    }

    // ── Move piece mesh ────────────────────────────────────────────────
    function syncMeshPosition(p) {
      if(p.type==="table"||p.type==="couch"||p.type==="chair") {
        positionBoxMesh(p.mesh,p.rMin,p.cMin,p.rMax,p.cMax,p.height);
        if(p.type==="chair") p.mesh.position.set(p.cMin+0.5,p.height/2,p.rMin+0.5);
      } else if(p.cells) {
        const ch=p.mesh.children;
        for(let i=0;i<ch.length&&i<p.cells.length;i++)
          ch[i].position.set(p.cells[i].c+0.5,p.height/2,p.cells[i].r+0.5);
      }
    }

    // ── selectPiece ────────────────────────────────────────────────────
    function selectPiece(p) {
      selectedPiece=p;
      btnDelete.disabled=!p;
      updateSelHighlight(p);
    }

    // ── Camera orbit ───────────────────────────────────────────────────
    let camTheta = Math.PI/4, camPhi = Math.PI/5.5, camZoom = 1.0;
    const CAM_TARGET = new THREE.Vector3(SIZE/2, 0, SIZE/2);

    function updateCamera() {
      const r = VIEW * camZoom * 0.95;
      const x = CAM_TARGET.x + r*Math.sin(camTheta)*Math.cos(camPhi);
      const y = CAM_TARGET.y + r*Math.sin(camPhi)*1.8;
      const z = CAM_TARGET.z + r*Math.cos(camTheta)*Math.cos(camPhi);
      camera.position.set(x, y, z);
      camera.lookAt(CAM_TARGET);
      const a = wrap.clientWidth / Math.max(1, wrap.clientHeight);
      const v = VIEW * camZoom;
      camera.left=-v*a; camera.right=v*a; camera.top=v; camera.bottom=-v;
      camera.updateProjectionMatrix();
    }
    updateCamera();

    // ── Raycasting helpers ─────────────────────────────────────────────
    const raycaster = new THREE.Raycaster();

    function toNDC(e) {
      const r = canvas.getBoundingClientRect();
      return new THREE.Vector2(
        ((e.clientX-r.left)/r.width)*2-1,
       -((e.clientY-r.top)/r.height)*2+1
      );
    }

    function getGridCellAt(e) {
      raycaster.setFromCamera(toNDC(e), camera);
      const hits = raycaster.intersectObjects(floorGroup.children);
      if(!hits.length) return null;
      const {row,col} = hits[0].object.userData;
      return {r:row, c:col};
    }

    function getPieceAt(e) {
      raycaster.setFromCamera(toNDC(e), camera);
      const objs=[];
      for(const p of pieces) {
        if(p.mesh instanceof THREE.Group)
          p.mesh.children.forEach(ch=>{if(ch.isMesh){ch._pid=p.id;objs.push(ch);}});
        else { p.mesh._pid=p.id; objs.push(p.mesh);
               p.mesh.children.forEach(ch=>{if(ch.isMesh){ch._pid=p.id;objs.push(ch);}});
        }
      }
      const hits=raycaster.intersectObjects(objs);
      if(!hits.length) return null;
      let obj=hits[0].object;
      while(obj&&obj._pid===undefined&&obj.userData.pieceId===undefined) obj=obj.parent;
      const pid = obj?.(obj._pid??obj.userData.pieceId);
      return pieces.find(p=>p.id===(obj?._pid ?? obj?.userData?.pieceId)) || null;
    }

    // ── Mouse state ────────────────────────────────────────────────────
    let orbiting=false, orbitLast={x:0,y:0};
    let mouseDownPiece=null, mouseDownCell=null;
    let mouseMoved=false, mouseDownTime=0;

    canvas.addEventListener("contextmenu", e=>e.preventDefault());

    canvas.addEventListener("mousedown", e => {
      if(gameOver) return;
      const cell  = getGridCellAt(e);
      const piece = getPieceAt(e);
      mouseDownPiece=piece; mouseDownCell=cell;
      mouseDownTime=Date.now(); mouseMoved=false;

      // Right mouse = orbit
      if(e.button===2 || e.button===1) {
        orbiting=true; orbitLast={x:e.clientX,y:e.clientY}; return;
      }
      if(e.button!==0) return;

      // Rug paint
      if(rugMode&&cell) {
        const key=`${cell.r},${cell.c}`;
        if(rugPaintCells.size<RUG_MAX_CELLS||rugPaintCells.has(key)) {
          rugPaintCells.add(key);
          const arr=[...rugPaintCells].map(k=>{const[r,c]=k.split(",").map(Number);return{r,c};});
          clearGhosts(); addGhostCells(arr,H_RUG,0xffd700,false);
          updateRugCounter();
        }
        return;
      }

      // Drag placed piece
      if(!couchMode&&!chairMode&&!lsofaMode&&!rugMode&&piece) {
        draggingPiece=piece;
        dragOffR=cell?cell.r-piece.rMin:0;
        dragOffC=cell?cell.c-piece.cMin:0;
        selectPiece(piece); return;
      }

      // Start selection rect (table placement)
      if(!couchMode&&!chairMode&&!lsofaMode&&!rugMode&&!piece&&cell) {
        selDragging=true; selStart={...cell};
        selRect={rMin:cell.r,cMin:cell.c,rMax:cell.r,cMax:cell.c};
        setSelRect(cell.r,cell.c,cell.r,cell.c,false);
        btnTable.disabled=false; return;
      }

      // Orbit fallback
      orbiting=true; orbitLast={x:e.clientX,y:e.clientY};
    });

    canvas.addEventListener("mousemove", e => {
      if(gameOver) return;
      const cell=getGridCellAt(e);
      mouseMoved=true;

      // Rug paint drag
      if(rugMode&&e.buttons===1&&cell) {
        const key=`${cell.r},${cell.c}`;
        if(rugPaintCells.size<RUG_MAX_CELLS||rugPaintCells.has(key)) {
          rugPaintCells.add(key);
          const arr=[...rugPaintCells].map(k=>{const[r,c]=k.split(",").map(Number);return{r,c};});
          clearGhosts(); addGhostCells(arr,H_RUG,0xffd700,false);
          updateRugCounter();
        }
        return;
      }

      // Placement ghosts
      if(couchMode&&cell) {
        const d=couchDims(cell.r,cell.c);
        clearGhosts();
        addGhostBox(d.rMin,d.cMin,d.rMax,d.cMax,H_COUCH,0xb86fc4,
          hasConflict(d.rMin,d.cMin,d.rMax,d.cMax));
        return;
      }
      if(chairMode&&cell) {
        clearGhosts();
        const conflict=gridOccupancy[cell.r]?.[cell.c]?.some(id=>{const p=pieces.find(x=>x.id===id);return p&&p.type!=="chair";})??false;
        addGhostBox(cell.r,cell.c,cell.r,cell.c,H_CHAIR,CHAIR_COLOR,conflict);
        return;
      }
      if(lsofaMode&&cell) {
        const cells=lsofaCells(cell.r,cell.c,lsofaGhostLenA,lsofaGhostLenB,lsofaVariant);
        const valid=cells.every(({r,c})=>r>=0&&c>=0&&r<SIZE&&c<SIZE);
        clearGhosts();
        if(valid) addGhostCells(cells,H_LSOFA,0x7a6bc4,hasConflictCells(cells));
        return;
      }

      // Drag piece
      if(draggingPiece&&cell) {
        const dR=draggingPiece.rMax-draggingPiece.rMin;
        const dC=draggingPiece.cMax-draggingPiece.cMin;
        const rMin=Math.max(0,Math.min(cell.r-dragOffR,SIZE-1-dR));
        const cMin=Math.max(0,Math.min(cell.c-dragOffC,SIZE-1-dC));
        if(draggingPiece.cells) {
          const dr=rMin-draggingPiece.rMin, dc=cMin-draggingPiece.cMin;
          eraseCells(draggingPiece.id,draggingPiece.cells);
          draggingPiece.cells=draggingPiece.cells.map(({r,c})=>({r:r+dr,c:c+dc}));
          draggingPiece.rMin=rMin;draggingPiece.cMin=cMin;
          draggingPiece.rMax=rMin+dR;draggingPiece.cMax=cMin+dC;
          stampCells(draggingPiece.id,draggingPiece.cells);
        } else {
          eraseRect(draggingPiece.id,draggingPiece.rMin,draggingPiece.cMin,draggingPiece.rMax,draggingPiece.cMax);
          draggingPiece.rMin=rMin;draggingPiece.cMin=cMin;
          draggingPiece.rMax=rMin+dR;draggingPiece.cMax=cMin+dC;
          stampRect(draggingPiece.id,rMin,cMin,rMin+dR,cMin+dC);
        }
        syncMeshPosition(draggingPiece);
        refreshAllColors();
        updateSelHighlight(draggingPiece);
        return;
      }

      // Selection rect drag
      if(selDragging&&cell) {
        const rMin=Math.min(selStart.r,cell.r),cMin=Math.min(selStart.c,cell.c);
        const rMax=Math.max(selStart.r,cell.r),cMax=Math.max(selStart.c,cell.c);
        selRect={rMin,cMin,rMax,cMax};
        setSelRect(rMin,cMin,rMax,cMax,hasConflict(rMin,cMin,rMax,cMax));
        btnTable.disabled=false; return;
      }

      // Orbit
