            placeCouch(d.rMin,d.cMin,d.rMax,d.cMax,ghostOrientation);
            refreshAllColors();
          }
          clearGhosts(); return;
        }
        if(chairMode) {
          const noConflict=!gridOccupancy[cell.r]?.[cell.c]?.some(id=>{
            const p=pieces.find(x=>x.id===id); return p&&p.type!=="chair";
          });
          if(noConflict) { placeChair(cell.r,cell.c); refreshAllColors(); }
          clearGhosts(); return;
        }
        if(lsofaMode) {
          const cells=lsofaCells(cell.r,cell.c,lsofaGhostLenA,lsofaGhostLenB,lsofaVariant);
          if(cells.every(({r,c})=>r>=0&&c>=0&&r<SIZE&&c<SIZE)&&!hasConflictCells(cells)) {
            placeLsofa(cell.r,cell.c,lsofaGhostLenA,lsofaGhostLenB,lsofaVariant);
            refreshAllColors();
          }
          clearGhosts(); return;
        }
      }

      // Click to select/deselect piece
      if(isClick&&!couchMode&&!chairMode&&!lsofaMode&&!rugMode) {
        const piece=getPieceAt(e);
        if(piece) selectPiece(piece);
        else if(!selDragging) { selectPiece(null); clearSelRect(); selRect=null; btnTable.disabled=true; }
      }

      orbiting=false;
    });

    canvas.addEventListener("mouseleave", () => {
      orbiting=false; selDragging=false; draggingPiece=null;
      clearGhosts();
    });

    canvas.addEventListener("wheel", e => {
