    btnChair.addEventListener("click",()=>{const was=chairMode;deactivateAll();if(!was){chairMode=true;btnChair.classList.add("active");}});
    btnRug.addEventListener("click",()=>{
      const was=rugMode;deactivateAll();
      if(!was){rugMode=true;btnRug.classList.add("active");rugPaintCells=new Set();rugCounterEl.style.display="block";updateRugCounter();}
    });
