        const dr=r-p.rMin,dc=c-p.cMin;
        p.cells=p.cells.map(({r:pr,c:pc})=>({r:pr+dr,c:pc+dc}));
        p.rMin=r;p.cMin=c;p.rMax=r+h;p.cMax=c+w;
