const CHAIR_COLOR=0x4ecdc4;

// Grid occupancy helpers
function stampRect(id,rMin,cMin,rMax,cMax){
  for(let r=rMin;r<=rMax;r++)for(let c=cMin;c<=cMax;c++)
    if(!gridOcc[r][c].includes(id))gridOcc[r][c].push(id);
}
function eraseRect(id,rMin,cMin,rMax,cMax){
  for(let r=rMin;r<=rMax;r++)for(let c=cMin;c<=cMax;c++)
    gridOcc[r][c]=gridOcc[r][c].filter(x=>x!==id);
}
function stampCells(id,cells){
  for(const{r,c}of cells)if(!gridOcc[r][c].includes(id))gridOcc[r][c].push(id);
}
function eraseCells(id,cells){
  for(const{r,c}of cells)gridOcc[r][c]=gridOcc[r][c].filter(x=>x!==id);
}
function hasConflict(rMin,cMin,rMax,cMax,ignoreId=null){
  for(let r=rMin;r<=rMax;r++)for(let c=cMin;c<=cMax;c++)
    for(const id of gridOcc[r][c])if(id!==ignoreId)return true;
  return false;
}
function hasConflictCells(cells,ignoreId=null){
  for(const{r,c}of cells){
    if(r<0||c<0||r>=SIZE||c>=SIZE)return true;
    for(const id of gridOcc[r][c])if(id!==ignoreId)return true;
  }
  return false;
}

// Mesh factory
function makeBoxMesh(cols,rows,height,colorHex){
  const geo=new THREE.BoxGeometry(cols*CELL,height,rows*CELL);
  const mat=new THREE.MeshLambertMaterial({color:colorHex});
  const mesh=new THREE.Mesh(geo,mat);
  mesh.castShadow=mesh.receiveShadow=true;
  const eMat=new THREE.LineBasicMaterial({color:0x000000,transparent:true,opacity:0.28});
  mesh.add(new THREE.LineSegments(new THREE.EdgesGeometry(geo),eMat));
  return mesh;
}
function positionBoxMesh(mesh,rMin,cMin,rMax,cMax,height){
  const cols=cMax-cMin+1,rows=rMax-rMin+1;
  mesh.position.set(cMin*CELL+cols*CELL/2,height/2,rMin*CELL+rows*CELL/2);
}

// Color updates
function setMeshColor(obj,hex){
