}
const COUCH_WIDTH=2,COUCH_LEN_DEFAULT=4;
function couchDims(r,c){
  if(ghostOrientation==='h')return{rMin:r,cMin:c,rMax:r+COUCH_WIDTH-1,cMax:Math.min(c+COUCH_LEN_DEFAULT-1,SIZE-1)};
  return{rMin:r,cMin:c,rMax:Math.min(r+COUCH_LEN_DEFAULT-1,SIZE-1),cMax:c+COUCH_WIDTH-1};
