// Chaos mode
const CHAOS_MS=2200,TICK_MS=500,CONFLICT_TIMEOUT=8000;
let chaosMode=false,chaosIv=null,tickIv=null,lastTick=0;

function teleportOne(p){
  const h=p.rMax-p.rMin,w=p.cMax-p.cMin;
  const r=Math.floor(Math.random()*(SIZE-h));
  const c=Math.floor(Math.random()*(SIZE-w));
  if(p.cells){
    eraseCells(p.id,p.cells);
    const dr=r-p.rMin,dc=c-p.cMin;
    p.cells=p.cells.map(({r:pr,c:pc})=>({r:pr+dr,c:pc+dc}));
    p.rMin=r;p.cMin=c;p.rMax=r+h;p.cMax=c+w;
    stampCells(p.id,p.cells);
  }else{
    eraseRect(p.id,p.rMin,p.cMin,p.rMax,p.cMax);
    p.rMin=r;p.cMin=c;p.rMax=r+h;p.cMax=c+w;
    stampRect(p.id,r,c,r+h,c+w);
  }
  syncMeshPos(p);
}
function chaosStep(){for(const p of pieces)teleportOne(p);refreshAllColors();updateSelHighlight(selectedPiece);}

function conflictTick(){
  const now=Date.now();
  if(!lastTick){lastTick=now;return;}
  for(const p of pieces){
    const bad=p.cells?hasConflictCells(p.cells,p.id):hasConflict(p.rMin,p.cMin,p.rMax,p.cMax,p.id);
    if(bad){if(!p.conflictSince)p.conflictSince=now;
            else if(now-p.conflictSince>CONFLICT_TIMEOUT){triggerGameOver(p.label+' sat in conflict too long!');return;}}
    else delete p.conflictSince;
  }
}
function triggerGameOver(msg){
  gameOver=true;clearInterval(chaosIv);clearInterval(tickIv);
  document.getElementById('gameover-msg').textContent=msg;
  document.getElementById('gameover-overlay').classList.add('visible');
}
function toggleChaos(){
  if(gameOver)return;
  chaosMode=!chaosMode;
  if(chaosMode){
    btnChaos.classList.add('active');chaosStep();
    chaosIv=setInterval(chaosStep,CHAOS_MS);tickIv=setInterval(conflictTick,TICK_MS);
  }else{
    btnChaos.classList.remove('active');
    clearInterval(chaosIv);clearInterval(tickIv);
    chaosIv=null;tickIv=null;lastTick=0;
    for(const p of pieces){delete p.conflictSince;refreshPieceColor(p);}
  }
}
