// Resize
function onResize(){
  const w=wrap.clientWidth,h=Math.max(1,wrap.clientHeight);
  renderer.setSize(w,h,false);updateCamera();
}
window.addEventListener('resize',onResize);
onResize();

// Render loop
function animate(){
  requestAnimationFrame(animate);
  if(selHighlight)selHighlight.material.opacity=0.22+0.18*Math.sin(Date.now()*0.004);
  renderer.render(scene,camera);
}
animate();
</script>
</body>
</html>
