// Keyboard
document.addEventListener('keydown',e=>{
  if(gameOver)return;
  const k=e.key.toLowerCase();

  // Arrow keys — move selected piece one cell at a time
  if(e.key==='ArrowUp'||e.key==='ArrowDown'||e.key==='ArrowLeft'||e.key==='ArrowRight'){
    e.preventDefault(); // prevent page scroll
    if(!selectedPiece)return;
    const p=selectedPiece;
    // Camera is isometric from a ~45° angle so we map arrows to grid axes intuitively:
    // ArrowUp    → row -1 (north), ArrowDown  → row +1 (south)
    // ArrowLeft  → col -1 (west),  ArrowRight → col +1 (east)
    let dr=0,dc=0;
    if(e.key==='ArrowUp')   dr=-1;
    if(e.key==='ArrowDown') dr=+1;
    if(e.key==='ArrowLeft') dc=-1;
    if(e.key==='ArrowRight')dc=+1;
    const h=p.rMax-p.rMin,w=p.cMax-p.cMin;
    const newRMin=Math.max(0,Math.min(p.rMin+dr,SIZE-1-h));
    const newCMin=Math.max(0,Math.min(p.cMin+dc,SIZE-1-w));
    if(newRMin===p.rMin&&newCMin===p.cMin)return; // already at edge
    if(p.cells){
      const ddr=newRMin-p.rMin,ddc=newCMin-p.cMin;
      eraseCells(p.id,p.cells);
      p.cells=p.cells.map(({r,c})=>({r:r+ddr,c:c+ddc}));
      p.rMin=newRMin;p.cMin=newCMin;p.rMax=newRMin+h;p.cMax=newCMin+w;
      stampCells(p.id,p.cells);
    }else{
      eraseRect(p.id,p.rMin,p.cMin,p.rMax,p.cMax);
      p.rMin=newRMin;p.cMin=newCMin;p.rMax=newRMin+h;p.cMax=newCMin+w;
      stampRect(p.id,newRMin,newCMin,newRMin+h,newCMin+w);
    }
    syncMeshPos(p);refreshAllColors();updateSelHighlight(p);
    return;
  }

  if(k==='escape'){deactivateAll();clearSelRectMesh();selRect=null;btnTable.disabled=true;selectPiece(null);return;}
  if(k==='r'){
    if(couchMode){ghostOrientation=ghostOrientation==='h'?'v':'h';clearGhosts();return;}
    if(lsofaMode){const vs=['se','sw','nw','ne'];lsofaVariant=vs[(vs.indexOf(lsofaVariant)+1)%4];clearGhosts();return;}
    if(selectedPiece){rotatePiece(selectedPiece);refreshAllColors();}
    return;
  }
  if(k==='d'||k==='delete'){deletePiece(selectedPiece);refreshAllColors();return;}
  if(k==='t'&&selRect){btnTable.click();return;}
  if(k==='c'){btnCouch.click();return;}
  if(k==='l'){btnLsofa.click();return;}
  if(k==='h'){btnChair.click();return;}
  if(k==='p'){btnRug.click();return;}
  if(k==='enter'&&rugMode&&rugPaintCells.size>0){
    const arr=[...rugPaintCells].map(k2=>{const[r,c]=k2.split(',').map(Number);return{r,c};});
    deactivateAll();placeRug(arr);refreshAllColors();return;
  }
});

