function rotatePiece(p){
  if(!p)return;
  rotatePieceDir(p,1); // 1 = CW (default)
}
// dir: +1 = CW (90° clockwise), -1 = CCW (90° counter-clockwise)
function rotatePieceDir(p,dir){
  if(!p)return;
  if(p.type==='table'||p.type==='couch'){
    const h=p.rMax-p.rMin,w=p.cMax-p.cMin;
    eraseRect(p.id,p.rMin,p.cMin,p.rMax,p.cMax);
    if(p.type==='couch')p.orientation=p.orientation==='h'?'v':'h';
    p.rMax=Math.min(p.rMin+w,SIZE-1);p.cMax=Math.min(p.cMin+h,SIZE-1);
    stampRect(p.id,p.rMin,p.cMin,p.rMax,p.cMax);rebuildMesh(p);
  }else if(p.type==='lsofa'){
    const vs=['se','sw','nw','ne'];
    const cur=vs.indexOf(p.variant);
    const newVariant=vs[((cur+(dir>0?1:3))%4)];
    const newCells=lsofaCells(p.anchorR,p.anchorC,p.lenA,p.lenB,newVariant);
    if(newCells.some(({r,c})=>r<0||c<0||r>=SIZE||c>=SIZE))return;
    eraseCells(p.id,p.cells);p.variant=newVariant;p.cells=newCells;
    const bb=bboxOf(newCells);p.rMin=bb.rMin;p.cMin=bb.cMin;p.rMax=bb.rMax;p.cMax=bb.cMax;
    stampCells(p.id,p.cells);rebuildMesh(p);
  }else if(p.type==='rug'){
    const H=p.rMax-p.rMin+1,W=p.cMax-p.cMin+1;
    let rotated;
    if(dir>0){
      // 90° CW: (dr,dc) → (dc, H-1-dr)
      rotated=p.cells.map(({r,c})=>{const dr=r-p.rMin,dc=c-p.cMin;return{r:p.rMin+dc,c:p.cMin+(H-1-dr)};});
    }else{
      // 90° CCW: (dr,dc) → (W-1-dc, dr)
      rotated=p.cells.map(({r,c})=>{const dr=r-p.rMin,dc=c-p.cMin;return{r:p.rMin+(W-1-dc),c:p.cMin+dr};});
    }
    const bb=bboxOf(rotated);
    const dr=Math.max(0,-bb.rMin)+Math.min(0,SIZE-1-bb.rMax);
    const dc=Math.max(0,-bb.cMin)+Math.min(0,SIZE-1-bb.cMax);
    const clamped=rotated.map(({r,c})=>({r:r+dr,c:c+dc}));
    eraseCells(p.id,p.cells);p.cells=clamped;
    const bb2=bboxOf(clamped);p.rMin=bb2.rMin;p.cMin=bb2.cMin;p.rMax=bb2.rMax;p.cMax=bb2.cMax;
    stampCells(p.id,p.cells);rebuildMesh(p);
  }
  updateSelHighlight(selectedPiece);
}

