323 | // dir: +1 = CW (90° clockwise), -1 = CCW (90° counter-clockwise)
324 | function rotatePieceDir(p,dir){
325 |   if(!p)return;
326 |   if(p.type==='table'||p.type==='couch'){
327 |     const h=p.rMax-p.rMin,w=p.cMax-p.cMin;
328 |     eraseRect(p.id,p.rMin,p.cMin,p.rMax,p.cMax);
329 |     if(p.type==='couch')p.orientation=p.orientation==='h'?'v':'h';
330 |     p.rMax=Math.min(p.rMin+w,SIZE-1);p.cMax=Math.min(p.cMin+h,SIZE-1);
331 |     stampRect(p.id,p.rMin,p.cMin,p.rMax,p.cMax);rebuildMesh(p);
332 |   }else if(p.type==='lsofa'){
333 |     const vs=['se','sw','nw','ne'];
334 |     const cur=vs.indexOf(p.variant);
335 |     const newVariant=vs[((cur+(dir>0?1:3))%4)];
336 |     const newCells=lsofaCells(p.anchorR,p.anchorC,p.lenA,p.lenB,newVariant);
337 |     if(newCells.some(({r,c})=>r<0||c<0||r>=SIZE||c>=SIZE))return;
338 |     eraseCells(p.id,p.cells);p.variant=newVariant;p.cells=newCells;
339 |     const bb=bboxOf(newCells);p.rMin=bb.rMin;p.cMin=bb.cMin;p.rMax=bb.rMax;p.cMax=bb.cMax;
340 |     stampCells(p.id,p.cells);rebuildMesh(p);
341 |   }else if(p.type==='rug'){
342 |     const H=p.rMax-p.rMin+1,W=p.cMax-p.cMin+1;
343 |     let rotated;
344 |     if(dir>0){
345 |       // 90° CW: (dr,dc) → (dc, H-1-dr)
346 |       rotated=p.cells.map(({r,c})=>{const dr=r-p.rMin,dc=c-p.cMin;return{r:p.rMin+dc,c:p.cMin+(H-1-dr)};});
347 |     }else{
348 |       // 90° CCW: (dr,dc) → (W-1-dc, dr)
349 |       rotated=p.cells.map(({r,c})=>{const dr=r-p.rMin,dc=c-p.cMin;return{r:p.rMin+(W-1-dc),c:p.cMin+dr};});
350 |     }
351 |     const bb=bboxOf(rotated);
352 |     const dr=Math.max(0,-bb.rMin)+Math.min(0,SIZE-1-bb.rMax);
353 |     const dc=Math.max(0,-bb.cMin)+Math.min(0,SIZE-1-bb.cMax);
354 |     const clamped=rotated.map(({r,c})=>({r:r+dr,c:c+dc}));
355 |     eraseCells(p.id,p.cells);p.cells=clamped;
356 |     const bb2=bboxOf(clamped);p.rMin=bb2.rMin;p.cMin=bb2.cMin;p.rMax=bb2.rMax;p.cMax=bb2.cMax;
357 |     stampCells(p.id,p.cells);rebuildMesh(p);
358 |   }
359 |   updateSelHighlight(selectedPiece);
360 | }
