// ═══════════════════════════════════════════════════════════════
//  Room Packer 3D  —  64×64×64 cube, 6 placeable faces
// ═══════════════════════════════════════════════════════════════
const SIZE=64, CELL=1.0;
const H_TABLE=0.70,H_COUCH=0.55,H_LSOFA=0.55,H_CHAIR=0.42,H_RUG=0.08;

// ── Three.js setup ────────────────────────────────────────────
const canvas=document.getElementById('three-canvas');
const wrap  =document.getElementById('canvas-wrap');
const renderer=new THREE.WebGLRenderer({canvas,antialias:true});
renderer.setPixelRatio(Math.min(window.devicePixelRatio,2));
renderer.shadowMap.enabled=true;
renderer.shadowMap.type=THREE.PCFSoftShadowMap;
renderer.setClearColor(0x0d0d1a);

const VIEW=SIZE*CELL*0.75;
const camera=new THREE.OrthographicCamera(-VIEW,VIEW,VIEW,-VIEW,-1000,1000);
const scene=new THREE.Scene();
scene.fog=new THREE.FogExp2(0x0d0d1a,0.006);

scene.add(new THREE.AmbientLight(0xffffff,0.55));
const sun=new THREE.DirectionalLight(0xfff8e7,0.85);
sun.position.set(80,120,80);sun.castShadow=true;
sun.shadow.mapSize.set(2048,2048);
sun.shadow.camera.left=-100;sun.shadow.camera.right=100;
sun.shadow.camera.top=100;sun.shadow.camera.bottom=-100;
sun.shadow.camera.near=1;sun.shadow.camera.far=500;
scene.add(sun);
scene.add(Object.assign(new THREE.DirectionalLight(0xc8d8ff,0.2),{position:new THREE.Vector3(-40,40,-20)}));

// ── Face definitions ──────────────────────────────────────────
// Each face of the 64³ cube has:
//   normal  : outward-facing direction (unit vec3)
//   origin  : world-space corner of the face (where u=0,v=0)
//   uAxis   : world-space direction of "column" axis on the face
//   vAxis   : world-space direction of "row" axis on the face
//   offset  : distance from centre to push pieces off the face surface
//
// The cube occupies [0,SIZE]³ in world space.
const HALF=SIZE/2;
const FACES={
  top:   {name:'TOP',    normal:new THREE.Vector3( 0, 1, 0), origin:new THREE.Vector3(0,SIZE,0),   uAxis:new THREE.Vector3(1,0,0), vAxis:new THREE.Vector3(0,0,1)},
  bottom:{name:'BOTTOM', normal:new THREE.Vector3( 0,-1, 0), origin:new THREE.Vector3(0,0,SIZE),   uAxis:new THREE.Vector3(1,0,0), vAxis:new THREE.Vector3(0,0,-1)},
  front: {name:'FRONT',  normal:new THREE.Vector3( 0, 0, 1), origin:new THREE.Vector3(0,SIZE,SIZE),uAxis:new THREE.Vector3(1,0,0), vAxis:new THREE.Vector3(0,-1,0)},
  back:  {name:'BACK',   normal:new THREE.Vector3( 0, 0,-1), origin:new THREE.Vector3(SIZE,SIZE,0),uAxis:new THREE.Vector3(-1,0,0),vAxis:new THREE.Vector3(0,-1,0)},
  left:  {name:'LEFT',   normal:new THREE.Vector3(-1, 0, 0), origin:new THREE.Vector3(0,SIZE,SIZE),uAxis:new THREE.Vector3(0,0,-1),vAxis:new THREE.Vector3(0,-1,0)},
  right: {name:'RIGHT',  normal:new THREE.Vector3( 1, 0, 0), origin:new THREE.Vector3(SIZE,SIZE,0),uAxis:new THREE.Vector3(0,0,1), vAxis:new THREE.Vector3(0,-1,0)},
};

// Convert face (u,v) grid coords to world position (top-left of cell)
function faceUVtoWorld(faceKey,u,v){
  const f=FACES[faceKey];
  return f.origin.clone()
    .addScaledVector(f.uAxis,u*CELL)
    .addScaledVector(f.vAxis,v*CELL);
}
// Center of a cell on a face
function faceCellCenter(faceKey,u,v,height){
  const f=FACES[faceKey];
  return f.origin.clone()
    .addScaledVector(f.uAxis,(u+0.5)*CELL)
    .addScaledVector(f.vAxis,(v+0.5)*CELL)
    .addScaledVector(f.normal,height/2);
}

// ── Cube wireframe ────────────────────────────────────────────
const cubeEdges=new THREE.LineSegments(
  new THREE.EdgesGeometry(new THREE.BoxGeometry(SIZE,SIZE,SIZE)),
  new THREE.LineBasicMaterial({color:0x334466,transparent:true,opacity:0.5})
);
cubeEdges.position.set(HALF,HALF,HALF);
scene.add(cubeEdges);

// ── Floor grids per face ──────────────────────────────────────
// We render a tile grid on each of the 6 faces.
const faceGroups={};
const tileGeoF=new THREE.BoxGeometry(CELL,0.06,CELL);
const matTileL=new THREE.MeshLambertMaterial({color:0xf0d9b5});
const matTileD=new THREE.MeshLambertMaterial({color:0xb58863});

for(const [faceKey,face] of Object.entries(FACES)){
  const group=new THREE.Group();
  for(let v=0;v<SIZE;v++){
    for(let u=0;u<SIZE;u++){
      // Build a thin tile oriented to the face
      const geo=new THREE.BoxGeometry(CELL*0.98,0.05,CELL*0.98);
      const mat=(u+v)%2===0?matTileL:matTileD;
      const m=new THREE.Mesh(geo,mat);
      m.receiveShadow=true;
      // Position at cell centre on the face surface
      const centre=faceCellCenter(faceKey,u,v,0);
      // Push slightly outward so it sits on the face
      centre.addScaledVector(face.normal,0.03);
      m.position.copy(centre);
      // Rotate tile to align with the face normal
      m.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),face.normal);
      m.userData={isTile:true,face:faceKey,u,v};
      group.add(m);
    }
  }
  faceGroups[faceKey]=group;
  scene.add(group);
}
