// ── Camera ────────────────────────────────────────────────────
let camTheta=Math.PI/4,camPhi=Math.PI/6,camZoom=1.0;
const CAM_TARGET=new THREE.Vector3(HALF,HALF,HALF);

function updateCamera(){
  const r=VIEW*camZoom;
  const x=CAM_TARGET.x+r*Math.sin(camTheta)*Math.cos(camPhi);
  const y=CAM_TARGET.y+r*Math.sin(camPhi)*1.6;
  const z=CAM_TARGET.z+r*Math.cos(camTheta)*Math.cos(camPhi);
  camera.position.set(x,y,z);camera.lookAt(CAM_TARGET);
  const a=wrap.clientWidth/Math.max(1,wrap.clientHeight),v=VIEW*camZoom;
  camera.left=-v*a;camera.right=v*a;camera.top=v;camera.bottom=-v;
  camera.updateProjectionMatrix();
}
updateCamera();

// ── Raycasting ────────────────────────────────────────────────
const raycaster=new THREE.Raycaster();
function toNDC(e){
  const r=canvas.getBoundingClientRect();
  return new THREE.Vector2(((e.clientX-r.left)/r.width)*2-1,-((e.clientY-r.top)/r.height)*2+1);
}

// Returns {face, u, v} of the active-face tile under the mouse
function getActiveFaceCellAt(e){
  raycaster.setFromCamera(toNDC(e),camera);
  const group=faceGroups[activeFace];
  const hits=raycaster.intersectObjects(group.children);
  if(!hits.length)return null;
  const{u,v}=hits[0].object.userData;
  return{face:activeFace,u,v};
}

// Returns the top-most piece under the mouse (any face)
function getPieceAt(e){
